-- Новые события имеют целевой cut_time и происходят из текущей доставки, выбранной детерминированно; batch_id является аудитом sink.
WITH ranked AS (SELECT p.*,row_number() OVER (PARTITION BY event_id ORDER BY topic,kafka_partition,kafka_offset,batch_id) AS rn FROM {{target:oil_stg__v_event_parsed}} p), fresh AS (SELECT e.* FROM {{target:oil_dds__event}} e WHERE NOT EXISTS (SELECT 1 FROM {{initial:oil_dds__event}} i WHERE i.event_id=e.event_id)) SELECT count(*) AS n FROM fresh e LEFT JOIN ranked p ON p.event_id=e.event_id AND p.rn=1 WHERE p.event_id IS NULL OR e.load_dts IS DISTINCT FROM {{cut_time}} OR e.record_source IS DISTINCT FROM p.topic OR e.batch_id IS DISTINCT FROM p.batch_id OR e.event_document IS DISTINCT FROM p.event_json;
